package com.example;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public final class App {

    private static final Logger log = LoggerFactory.getLogger(App.class);

    public static void main(String[] args) {
        log.info("Application started");
        log.debug("Debugging detail visible when debug logging is enabled");

        var greeter = new Greeter();
        log.info(greeter.greet("World"));

        log.info("Application finished");
    }
}

package com.example;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Greeter {

    private static final Logger log = LoggerFactory.getLogger(Greeter.class);

    public String greet(String name) {
        log.debug("Building greeting for {}", name);
        return "Hello, " + name + "!";
    }
}

package com.example;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class GreeterTest {

    @Test
    void greetsByName() {
        assertEquals("Hello, World!", new Greeter().greet("World"));
    }
}
